  (320, '함께 읽다가 서로 다른 결말을 골랐다면 뭘 해 볼까요?', array['서로 한 문장씩 바꿔 읽어 봐요.', '각자의 결말에 제목을 지어 줘요.', '어느 쪽 주인공이 잠을 잘지 얘기해요.']),
  (325, '상대가 만든 잡지에 실린다면 어떤 나를 소개하고 싶나요?', array['낯선 동네 간판 앞에 꼭 멈추는 저요.', '찢어진 우산도 고쳐 쓰는 모습이요.', '매일 다른 샌드위치를 싸 보는 취미요.']),
  (331, '손글씨로 옮겨 적어서 좋아하는 사람에게 들려주고 싶은 글은요?', array['할머니가 알려 준 짧은 조리법이요.', '친구가 보낸 여행 엽서 한 장이요.', '겨울 풍경이 선명한 짧은 시요.']),
  (338, '밤늦게 서로 책 얘기를 하다가 한 쪽 더 읽게 되는 순간은요?', array['말없던 인물이 갑자기 입을 열 때요.', '끝난 줄 알았던 사건에 편지가 올 때요.', '다음 장 제목이 유난히 엉뚱할 때요.']),
  (345, '이제 막 가까워진 사람에게 줄 책의 첫 장에 무슨 말을 남길까요?', array['천천히 읽고 좋아한 장면만 들려줘요.', '이 표지 색이 꼭 네 우산 같았어.', '끝까지 안 읽어도 우리 간식은 먹자.']),
  (351, '나를 처음 만난 사람이 그림책 속 친구로 기억한다면 어떤 동물이 좋나요?', array['길을 자꾸 묻는 작은 두더지요.', '노래는 서툴지만 잘 듣는 귀뚜라미요.', '사람보다 표정이 다양한 수달이요.']),
  (357, '한 장짜리 동네 신문을 낸다면 어떤 소식이 첫 기사일까요?', array['놀이터 은행나무에 새 둥지가 생겼어요.', '사라졌던 빵집의 소보로가 돌아왔어요.', '우산 수리대에 첫 손님이 왔어요.']),
  (365, '미술관 데이트에서 작품 하나를 함께 보는 순서를 정한다면요?', array['먼저 각자 보고 마지막에 제목을 읽어요.', '제목을 같이 읽고 단서를 찾아봐요.', '서로 제목 하나씩 지어 주고 비교해요.']),
  (368, '그림 한 점을 만져 볼 수 있다면 어떤 부분이 궁금한가요?', array['바다가 하얗게 솟은 물감 자국이요.', '캔버스 밖으로 삐져나온 실 끝이요.', '반질반질해 보이는 사과 껍질이요.']),
  (378, '둘의 첫 전시에 소중한 일상 물건을 하나씩 낸다면, 내 물건은요?', array['동네 운동장 흙 묻은 축구공이요.', '오랫동안 쓰다가 닳은 나무 숟가락이요.', '바람 없이 조금씩 도는 모빌이요.']),
  (384, '함께 간 전시에서 서로 줄 엽서 한 장씩 고른다면 내 기준은요?', array['다시 한참 들여다보고 싶은 그림이요.', '받을 사람이 좋아할 색의 작품요.', '처음엔 지나쳤는데 계속 생각난 그림이요.']),
  (390, '둘이 벽화 봉사를 나간다면 나란히 그리고 싶은 장면은요?', array['벽의 금을 따라 자라는 덩굴이요.', '아이 키만 한 숨은 고양이들이요.', '빗물이 흐르면 완성되는 작은 폭포요.']),
  (392, '요즘 내 기분을 새로 만난 사람에게 색연필 세 자루로 보여 준다면요?', array['벽돌색, 우윳빛, 진한 연두요.', '연필심 회색에 귤색과 남색이요.', '식탁의 꿀색, 초록, 토마토색이요.']),
  (400, '처음 만난 날 창가에 앉아 누군가와 오래 바라보고 싶은 풍경은요?', array['가로등 아래 둥글게 모인 낙엽이요.', '지붕 사이로 반쪽 보이는 달이요.', '전봇줄을 줄지어 건너는 새들이요.']),
  (407, '같은 작품 앞에서 둘의 반응이 다르면 뭐가 궁금해요?', array['상대가 처음 본 부분부터 궁금해요.', '그 색이 떠올리게 한 기억이요.', '왜 웃음이 났는지 듣고 싶어요.']),
  (412, '취향이 닮았나 궁금할 때 상대에게 보여 주고 싶은 색 조합은요?', array['청포도와 짙은 파란 접시요.', '밤색 구두 옆에 떨어진 노란 잎이요.', '비 온 뒤 보도블록의 자줏빛이요.']),
  (415, '서로 그림 실력을 걱정하지 않고 초상화를 바꿔 그릴 방법은요?', array['종이를 안 보고 한 줄로 그려요.', '얼굴 대신 좋아하는 물건을 그려요.', '십 초마다 서로 종이를 바꿔요.']),
  (424, '말없이 나란히 앉아도 편할 것 같은 조각 정원의 자리는 어디인가요?', array['바람이 불면 쇳소리가 나는 조각이요.', '사람이 앉으면 꽃잎이 되는 벤치요.', '해가 지면 그림자가 길어지는 새요.']),
  (431, '산책 중인 상대에게 빈 액자를 건넨다면 함께 담고 싶은 장면은요?', array['아파트 사이로 한 줄 보이는 노을이요.', '정류장에 나란히 선 알록달록한 장화요.', '꽃집 유리창에서 자는 고양이요.']),
  (435, '처음 보는 추상화 앞에서 말을 꺼낸다면 첫마디는요?', array['저 초록은 약간 시큼해 보여요.', '저 선을 손가락으로 따라가 볼래요?', '제일 먼저 어디를 봤는지 궁금해요.']),
  (444, '둘이 만든 전시에 관람객 참여 코너를 넣는다면요?', array['오늘 기분을 색 점 하나로 찍어요.', '종이 새를 접어 창가에 매달아요.', '빈 말풍선에 작품의 혼잣말을 써요.']),
  (450, '작은 박물관 한 칸으로 내 취향을 상대에게 소개한다면 뭘 모을까요?', array['모양이 다 다른 오래된 열쇠요.', '지역마다 그림이 다른 버스표요.', '책상 서랍의 짝 잃은 단추들이요.']),
  (455, '작품 설명을 소리로 들려준다면 어떤 목소리가 어울릴까요?', array['옆에서 슬쩍 힌트를 주는 친구요.', '그림 속 강아지의 느긋한 목소리요.', '작가가 재료를 고를 때의 혼잣말이요.']),
  (461, '같은 사과를 보고 둘이 그린 그림은 뭐가 달라질까요?', array['저는 껍질의 작은 점부터 그려요.', '저는 접시에 비친 붉은빛을 볼래요.', '한입 베어 문 단면이 그리고 싶어요.']),
  (463, '상대가 그린 동그라미 하나로 그림 이어 그리기를 시작한다면요?', array['담 넘어 얼굴을 내민 보름달이요.', '한 바퀴 돌기 직전의 관람차요.', '소풍 가방에서 굴러나온 귤이요.']),
  (471, '날씨가 바뀌면 같이 다시 보러 가자고 하고 싶은 야외 작품은요?', array['비 오는 날에만 글씨가 나타나요.', '해가 비치면 바닥에 무지개가 생겨요.', '바람이 불수록 나뭇잎이 춤춰요.']),
  (478, '데이트한 둘의 감상을 그림으로 방명록에 남긴다면 무엇을 그릴까요?', array['두 눈이 초승달이 된 얼굴이요.', '나오면서 발걸음이 가벼워진 신발이요.', '마음에 남은 파란색 한 칸이요.']),
  (485, '무언극처럼 말 없이도 데이트 상대에게 전할 수 있는 부탁은요?', array['옆자리 고양이가 잠들었으니 조용히요.', '매듭이 풀린 신발 끈 좀 봐 달라고요.', '뜨거운 군고구마를 반으로 나누자고요.']),
  (487, '연극 시작 전, 옆 사람과 이야기를 상상하게 만드는 무대 소품은요?', array['저절로 울리는 낡은 탁상전화요.', '한 켤레인 듯 짝이 다른 장화요.', '물이 뚝뚝 떨어지는 닫힌 우산이요.']),
  (497, '춤을 처음 같이 배운다면 어떤 방식이 편할까요?', array['음악 없이 발 순서부터 맞춰요.', '틀려도 그대로 한 곡을 춰 봐요.', '상대를 거울처럼 따라 하며 웃어요.']),
  (503, '데이트 중 뮤지컬처럼 노래가 터져 나올 것 같은 순간은요?', array['마지막 붕어빵을 반씩 나눠 먹을 때요.', '길을 잘못 들었는데 바다가 보일 때요.', '둘 다 같은 후렴을 흥얼거릴 때요.']),
  (506, '인형극 무대 위에서 주인공이 될 물건을 고른다면요?', array['혼자서도 당당히 서는 빗자루요.', '매일 다른 손님을 만나는 찻잔이요.', '잃어버린 짝을 찾아 나선 양말이요.']),
  (512, '같이 연극을 만든다면 내 손으로 상대에게 보여주고 싶은 무대 효과는요?', array['천으로 파도 소리를 만들어 볼래요.', '깜짝 등장하는 달을 들어 올릴래요.', '주인공 주머니에 편지를 넣어 둘래요.']),
  (518, '커튼콜에서 배우들이 어떤 인사를 하면 기억에 남을까요?', array['서로 의자를 당겨 주며 인사해요.', '극 중 단골 몸짓을 다 같이 해요.', '무대 뒤 스태프를 한 명씩 불러요.']),
  (523, '즉흥극을 보러 간 상대가 단어를 하나만 골라 달라고 한다면요?', array['누구나 한 번 잃어본 장갑이요.', '열기만 해도 소동이 날 도시락이요.', '계속 울릴 것 같은 초인종이요.']),
  (532, '어린이 연극의 악당이라면 무슨 귀여운 약점이 있을까요?', array['누가 하품하면 꼭 따라 하품해요.', '갓 구운 빵 냄새에 길을 잃어요.', '고양이가 앉으면 자리에서 못 일어나요.']),
  (537, '누군가에게 다가가는 마음을 춤의 한 동작으로 표현한다면요?', array['발끝으로 다가가서 설렘을 보여요.', '주먹을 천천히 펴서 편안함을 전해요.', '팔을 내밀었다 거두며 망설여요.']),
  (545, '무대 의상을 한 벌 지을 때 어느 부분에 비밀을 숨길까요?', array['소맷단 안쪽에 웃는 얼굴을 수놓아요.', '치맛단에 걸을 때 울릴 방울을 달아요.', '안주머니 속에 조그만 별을 그려요.']),
  (547, '관객에게 단 한 번 질문을 건네는 연극이라면요?', array['이 편지를 지금 뜯어도 될까요?', '여기 두 의자 중 어디에 앉을까요?', '저 문 뒤에 누구 목소리가 들리나요?']),
  (553, '캠핑 데이트에서 손전등으로 그림자극을 보여 준다면 첫 주인공은요?', array['부리가 자꾸 벌어지는 수다쟁이 새요.', '귀보다 발이 긴 엉뚱한 토끼요.', '꼬리를 제 그림자로 착각한 여우요.']),
  (559, '처음 같이 간 공연에서 앙코르가 시작되기 전, 뭘 하며 기다릴까요?', array['박수 리듬이 맞는 사람을 찾아요.', '친구와 듣고 싶은 곡을 하나씩 꼽아요.', '무대에 다시 불이 들어오는 걸 지켜봐요.']),
  (567, '우리 둘의 평범한 대화를 연극 제목으로 지으면요?', array['귤은 어디서부터 까야 할까요?', '버스 한 대만 더 보내기로 했다.', '아무도 마지막 만두를 집지 않았다.']),
  (574, '소극장 맨 앞에서 공연을 보고 나와 상대와 이야기하고 싶은 디테일은요?', array['대사 직전 배우가 숨을 고르는 순간이요.', '구두로 바닥에 박자를 만드는 모습이요.', '배경을 바꾸는 손들의 빠른 호흡요.']),
  (581, '배우에게 줄 꽃 대신 작은 선물을 꾸린다면 뭘 넣을까요?', array['커튼콜 그림을 그린 엽서 한 장이요.', '분장실에서 먹기 편한 작은 귤이요.', '그날 가장 웃은 장면을 적은 메모요.']),
  (588, '서로에게 5초짜리 안무를 가르친다면 첫 동작은요?', array['한 손으로 모자를 고쳐 쓰는 시늉이요.', '양 어깨를 한 번씩 번갈아 올려요.', '발뒤꿈치로 바닥에 하트를 그려요.']),
  (594, '데이트 상대가 나를 만화로 그려 준다면 꼭 닮았으면 하는 부분은요?', array['좋은 냄새를 맡으면 커지는 콧구멍이요.', '웃을 때 한쪽만 접히는 눈이요.', '뭘 생각하면 신발 끝이 움직여요.']),
  (600, '처음 만난 상대가 함께 웃어 줬으면 하는 네 컷 만화의 반전은요?', array['주인공이 기다린 손님이 택배였어요.', '무서운 발소리의 주인은 아기 오리예요.', '비밀 쪽지엔 장보기 목록뿐이었어요.']),
  (606, '만화 말풍선 밖의 효과음을 하나 발명한다면요?', array['식은 커피에 얼음 녹는 소리, 사륵똑.', '웃음 참다가 새는 콧소리, 풉힝.', '햇볕에 이불이 부푸는 소리, 보송푹.']),
  (612, '바쁜 사람 책상에 웃음을 놓아 줄 달력 캐릭터를 그린다면요?', array['날짜 위에서 턱을 괸 곰이요.', '휴일마다 배낭을 메는 참새요.', '넘길 때마다 수염이 자라는 고양이요.']),
  (615, '아직 어색한 사이에 직접 만든 스티커를 살짝 보내고 싶은 때는요?', array['무사히 도착했다는 인사 대신 보내요.', '친구의 첫 성공을 축하하고 싶을 때요.', '쑥스러워서 고맙단 말이 늦었을 때요.']),
  (622, '볼 때마다 마음이 놓이는 그림체는 어떤 느낌인가요?', array['테두리가 살짝 떨리는 연필 그림이요.', '솜이불처럼 색이 번지는 수채화요.', '눈 두 점만으로 표정이 보이는 그림이요.']),
  (627, '그림만으로 데이트 약속 장소를 알려 준다면 어떤 표지가 좋을까요?', array['쉼터 벤치에 나란히 놓인 모자 두 개요.', '우산을 쓴 곰이 있는 정류장 표지요.', '손을 마주 흔드는 광장의 표지판이요.']),
  (635, '첫 만남의 어색함을 풀어 줄 만큼 이야기거리가 있는 메뉴판은요?', array['잔 크기를 실제 그림으로 보여 줘요.', '첫 장만 봐도 따뜻한 차를 찾을 수 있어요.', '손때 묻은 글씨 옆에 컵 자국이 있어요.']),
  (640, '한글 자음 하나로 나만의 도장을 판다면 어떤 모양일까요?', array['미음을 창문처럼 파고 꽃을 놓을래요.', '시옷을 산봉우리 두 개로 만들래요.', '이응을 보름달처럼 둥글게 팔래요.']),
  (644, '천 가방을 하나씩 꾸미며 취향을 나눈다면 내 것은 어떻게 칠할까요?', array['손잡이 안쪽을 노랗게 칠할래요.', '바닥에 파란 물결 한 줄을 그려요.', '옆구리에 작은 빨간 점을 찍어요.']),
  (650, '도예 데이트에서 내 손에 꼭 맞는 잔을 만든다면 어디부터 다듬을까요?', array['두 손가락이 편하게 들어갈 손잡이요.', '두 손으로 감싸기 좋은 둥근 몸통이요.', '다 마시면 나타나는 바닥의 작은 그림이요.']),
  (657, '좋아하는 사람에게 건넬 작은 선물, 종이 한 장으로 어떻게 포장할까요?', array['접힌 모서리에 잎사귀 하나를 꽂아요.', '받는 사람 별명을 큼직이 써요.', '끈 대신 종이를 길게 접어 묶어요.']),
  (664, '메시지 대신 건네받은 짧은 손글씨가 유독 다정해 보일 때는요?', array['받침까지 또박또박 눌러 썼을 때요.', '마지막에 웃는 얼굴을 동그랗게 그릴 때요.', '급히 썼는데도 이름은 반듯하게 썼을 때요.']),
  (670, '가게 간판 글자를 새로 만든다면 어떤 가게가 재미있을까요?', array['속이 다 보이는 둥근 만두집 글씨요.', '글자가 실처럼 이어지는 수선집이요.', '빗방울이 점처럼 찍힌 우산집이요.']),
  (673, '눈을 감은 상대에게 소리 퀴즈를 낸다면 뭘 들려줄까요?', array['겨울 이불 커버를 털 때 나는 팡 소리요.', '테이프 끝이 갑자기 떨어지는 소리요.', '따뜻한 물이 주전자에 차는 소리요.']),
  (681, '둘만의 산책길을 소리 지도로 만들 때 첫 표시는 무엇이면 좋을까요?', array['모퉁이에서 울리는 자전거 종소리요.', '목욕탕 굴뚝 아래서 우는 비둘기요.', '해 질 때 공원에서 튀는 농구공 소리요.']),
  (688, '처음 만난 날의 어색한 침묵을 풀어 줄 반가운 소리는요?', array['긴장하던 사람이 먼저 웃는 소리요.', '문 앞에서 들리는 가벼운 노크요.', '따뜻한 차를 따라 주는 소리요.']),
  (691, '데이트 중 비가 와서 창가에 앉았다면 잠깐 같이 듣고 싶은 소리는요?', array['처마 끝에서 일정하게 떨어지는 물소리요.', '차가 먼 길을 천천히 지나는 소리요.', '젖은 잎에서 한꺼번에 쏟아지는 빗소리요.']),
  (700, '멀리 있는 사람에게 여행 엽서 대신 소리를 보내면 무엇을 녹음할까요?', array['멀리 배가 떠날 때 울린 뱃고동이요.', '돌길을 지나는 여행 가방 바퀴 소리요.', '기차 문이 닫히기 전 역의 종소리요.']),
  (705, '내가 오래 아끼는 물건을 상대에게 보여 준다면 어떤 매력을 짚어 줄까요?', array['나무 책상 모서리가 손에 잘 맞을 때요.', '자주 넘긴 책장이 부드럽게 휘어질 때요.', '손잡이만 반들반들한 주전자를 볼 때요.']),
  (709, '좋아하는 사람에게 보낼 첫 편지의 우표를 직접 만든다면 뭘 그릴까요?', array['입에 편지를 문 느긋한 달팽이요.', '두 집의 창문을 잇는 빨랫줄이요.', '작은 풀꽃 사이로 난 자전거 길이요.']),
  (716, '상대가 선물한 새 노트 첫 장에 꼭 남겨 두고 싶은 그림은요?', array['오늘 신었던 양말의 줄무늬요.', '눈앞에 놓인 컵의 손잡이만 그려요.', '눈 감고 그린 선에 이름을 붙여요.']),
  (722, '둘이 예술 축제에 작은 부스를 낸다면 무얼 해 주고 싶나요?', array['손님이 고른 색으로 종이꽃을 접어요.', '두 줄짜리 사연을 네 컷으로 그려요.', '오늘 기분에 맞는 손박수 리듬을 짜요.']),
  (728, '하루 끝에 각자 해 보고 서로 나누고 싶은 작은 예술 습관은요?', array['잘 들은 소리 하나를 말로 적어요.', '창밖 하늘색으로 달력 한 칸을 칠해요.', '오늘 웃은 순간만 세 컷으로 남겨요.']);
